  Request,
  Response,
  'preload'
> {
  return { access: 'preload' } as InvokeDeclaration<Request, Response, 'preload'>
}

export function payload<Payload>(): PayloadDeclaration<Payload> {
  return {} as PayloadDeclaration<Payload>
